      "footnotes": {
        "1": {
          "title": "〔注1〕Anthropic S-1 招股书核心财务机制：存量推理盈利 vs 增量训练吞噬",
          "content": "在传统 SaaS 软件公司中，软件研发属于前置固定成本，规模扩大后边际毛利率通常高达 75%～85%。而 Anthropic 的 S-1 招股书揭示了前沿大模型实验室独特的双层账本结构：如果仅看当前已训练完成的存量模型（如 Claude 3.5/4 系列）对外提供 API 与企业订阅服务，其扣除推理算力（Inference Compute）后的业务毛利其实相当可观；但为了在下一代前沿模型竞赛中不被甩开，公司必须将全部毛利乃至数百亿美元的外部融资重新投入下一代基座模型的预训练与强化学习（Training Compute）。这意味着“训练算力开支”并非一次性资本投入，而是每一代模型迭代都必须成倍追加的准经常性吞金兽。"
        },
        "2": {
          "title": "〔注2〕按量计费（Usage-Based Billing）与 AI 时代的收入确认",
          "content": "传统 SaaS 采用按席位包年/包月（Seat-based Subscription）收费，因为多一个用户登录几乎不增加服务器成本；而大模型每一次生成 Token 都会直接消耗昂贵的 GPU 推理算力，若继续采用固定包月极易被高频重度用户击穿毛利。因此 AI 行业普遍转向“基础订阅 + 按实际 Token/算力消耗量阶梯计费（Usage-based billing）”，这对底层计费系统的实时并发计量、欠费熔断与动态账单核销提出了很高要求，成为 Stripe Billing 等金融基础设施的新增长引擎。"
        },
        "3": {
          "title": "〔注3〕前沿实验室的无限股权稀释（Endless Dilution）风险",
          "content": "由于单次前沿模型训练成本向数十亿乃至百亿美元量级跃升，大模型实验室无法仅靠经营性现金流自我造血，必须持续通过增发新股或发行附带转股权的可转换债券（Convertible Notes，如亚马逊与谷歌对 Anthropic 的多轮巨额注资）换取云算力代金券与现金。对二级市场普通公众股东而言，这意味着即便公司营收高速增长，只要算力军备竞赛不止，每股收益（EPS）与持股比例就会面临持续的增发摊薄。"
        },
        "4": {
          "title": "〔注4〕商业俚语 “Open the Kimono”（掀开底牌 / 彻底公开账目）",
          "content": "源自 20 世纪后期华尔街与硅谷并购尽调行话，字面意为“解开和服”，在商业语境中专指原本高度保密的私营企业在递交 IPO 招股书（Form S-1）或进入并购排他期时，向监管机构与公众投资者首次公开内部真实的财务账本、客户集中度与核心成本结构。"
        }
      },
