          "content": "在工业成本会计中，单一产出设施（如医用加速器或专用研究堆）的全部固定资产折旧（Depreciation）与运维成本（OPEX）必须 100% 由同位素产品承担；而在商用聚变反应堆或聚变-裂变混合堆架构下，反应堆主业是向外网出售电力，包层中利用余量高能中子照射靶件生产同位素属于“联产品/副产品”（Co-product）。这不仅能用高毛利的医用同位素反哺聚变电站的早期商业化现金流，还能在远期将工业同位素的边际制造成本压低一至两个数量级。"
