          "content": "在“谁在真正买单（Who Is Paying?）”这一问题上，前期是亚马逊（AWS）与谷歌（GCP）通过百亿美元级的可转换票据（Convertible Notes）与优先股买单，但云巨头付出的投资款很快以“云算力采购合同收入”的形式回流到了 AWS 和 Google Cloud 的利润表里；而当 Anthropic 通过 IPO 走向公开市场后，真正为下一代训练算力黑洞买单并承担无限股权摊薄（Dilution）的，将变成二级市场的机构与散户投资者。"
