      "footnotes": {
        "1": {
          "title": "〔注1〕CPA 财务准则穿透：什么是供应商融资安排（Supplier Finance Programs, ASC 405-50）？",
          "content": "根据美国财务会计准则委员会（FASB）最新修订并强制生效的《ASC 405-50：负债——供应商融资安排披露》（对应国际准则 IAS 7 修订），大型买方企业（如亚马逊）在采购高价值服务器硬件时，由合作银行或银团先行向硬件供应商（如英伟达、富士康、广达等代工厂）垫付货款，亚马逊则利用自身极高的信用评级将原本 60～90 天的应付账款账期拉长至更周期，或转为结构化分期付款。自 2023/2024 财年起，SEC 与 FASB 强制要求美股上市公司必须在季报附注中单独披露此类供应链融资的授信总额与期末未偿余额，防止巨头借此隐匿真实债务杠杆。"
        },
        "2": {
          "title": "〔注2〕800 亿美元算力供应链融资对自由现金流（FCF）与资本开支（Capex）的修饰效应",
          "content": "在 AI 算力军备竞赛中，华尔街高度警惕云厂商因资本开支（Capex）暴增导致自由现金流（Free Cash Flow = 经营活动现金流 - 资本开支）转负（例如本周 Meta 因负自由现金流遭标普下调评级展望）。亚马逊通过高达 800 亿美元的技术基础设施供应商融资安排，能够在物理上率先拿到价值 800 亿美元的 AI 服务器并投入 AWS 运营创收，同时将当期真实的现金流出递延至未来数个季度分期偿付，从而在短期内平滑现金流量表上的“购建固定资产支付的现金”冲击，保住当期自由现金流指标。"
        }
      },
